(** ** Enumerations as numbers (HOL [t2num], [num2t]) *)

Definition ShiftType2num (x : ShiftType) : N :=
  match x with
  | ShiftType_LSL => 0
  | ShiftType_LSR => 1
  | ShiftType_ASR => 2
  | ShiftType_ROR => 3
  end.
Definition num2ShiftType (n : N) : ShiftType :=
  if n =? 0 then ShiftType_LSL
  else if n =? 1 then ShiftType_LSR
  else if n =? 2 then ShiftType_ASR
  else if n =? 3 then ShiftType_ROR
  else ARB.

Definition ExtendType2num (x : ExtendType) : N :=
  match x with
  | ExtendType_UXTB => 0
  | ExtendType_UXTH => 1
  | ExtendType_UXTW => 2
  | ExtendType_UXTX => 3
  | ExtendType_SXTB => 4
  | ExtendType_SXTH => 5
  | ExtendType_SXTW => 6
  | ExtendType_SXTX => 7
  end.
Definition num2ExtendType (n : N) : ExtendType :=
  if n =? 0 then ExtendType_UXTB
  else if n =? 1 then ExtendType_UXTH
  else if n =? 2 then ExtendType_UXTW
  else if n =? 3 then ExtendType_UXTX
  else if n =? 4 then ExtendType_SXTB
  else if n =? 5 then ExtendType_SXTH
  else if n =? 6 then ExtendType_SXTW
  else if n =? 7 then ExtendType_SXTX
  else ARB.

Definition MemBarrierOp2num (x : MemBarrierOp) : N :=
  match x with
  | MemBarrierOp_DSB => 0
  | MemBarrierOp_DMB => 1
  | MemBarrierOp_ISB => 2
  end.
Definition num2MemBarrierOp (n : N) : MemBarrierOp :=
  if n =? 0 then MemBarrierOp_DSB
  else if n =? 1 then MemBarrierOp_DMB
  else if n =? 2 then MemBarrierOp_ISB
  else ARB.

Definition RevOp2num (x : RevOp) : N :=
  match x with
  | RevOp_RBIT => 0
  | RevOp_REV16 => 1
  | RevOp_REV32 => 2
  | RevOp_REV64 => 3
  end.
Definition num2RevOp (n : N) : RevOp :=
  if n =? 0 then RevOp_RBIT
  else if n =? 1 then RevOp_REV16
  else if n =? 2 then RevOp_REV32
  else if n =? 3 then RevOp_REV64
  else ARB.

Definition SystemHintOp2num (x : SystemHintOp) : N :=
  match x with
  | SystemHintOp_NOP => 0
  | SystemHintOp_YIELD => 1
  | SystemHintOp_WFE => 2
  | SystemHintOp_WFI => 3
  | SystemHintOp_SEV => 4
  | SystemHintOp_SEVL => 5
  end.
