  if n =? 0 then SystemHintOp_NOP
  else if n =? 1 then SystemHintOp_YIELD
  else if n =? 2 then SystemHintOp_WFE
  else if n =? 3 then SystemHintOp_WFI
  else if n =? 4 then SystemHintOp_SEV
  else if n =? 5 then SystemHintOp_SEVL
