(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "X_def" *)
Definition X {Nw : N} (n : word5) : (arm8_state -> (word Nw)) :=
  (fun (state : arm8_state) => (if (bool_decide (n = (n2w 31 : word5))) then (n2w 0 : (word Nw)) else ((w2w (arm8_state_REG state n)) : (word Nw)))).

(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "write'X_def" *)
