(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "write'SP_def" *)
Definition write'SP {Nw : N} (value' : (word Nw)) : (arm8_state -> arm8_state) :=
  (fun (state : arm8_state) => (let v := ((w2w value') : word64) in
 (if (negb (ProcState_SPS (arm8_state_PSTATE state))) then (arm8_state_SP_EL0_fupd (fun _ => v) state) else (let scrut' := (ProcState_EL (arm8_state_PSTATE state)) in (if bool_decide (scrut' = (n2w 0 : word2)) then (arm8_state_SP_EL0_fupd (fun _ => v) state) else (if bool_decide (scrut' = (n2w 1 : word2)) then (arm8_state_SP_EL1_fupd (fun _ => v) state) else (if bool_decide (scrut' = (n2w 2 : word2)) then (arm8_state_SP_EL2_fupd (fun _ => v) state) else (if bool_decide (scrut' = (n2w 3 : word2)) then (arm8_state_SP_EL3_fupd (fun _ => v) state) else (let v1 := scrut' in (ARB : arm8_state)))))))))).

(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "TranslationRegime_def" *)
Definition TranslationRegime (state : arm8_state) : word2 :=
  (if (negb (bool_decide ((ProcState_EL (arm8_state_PSTATE state)) = (n2w 0 : word2)))) then (ProcState_EL (arm8_state_PSTATE state)) else (n2w 1 : word2)).

(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "SCTLR_def" *)
Definition SCTLR (state : arm8_state) : SCTLRType :=
  (let scrut' := (TranslationRegime state) in (if bool_decide (scrut' = (n2w 1 : word2)) then (arm8_state_SCTLR_EL1 state) else (if bool_decide (scrut' = (n2w 2 : word2)) then (arm8_state_SCTLR_EL2 state) else (if bool_decide (scrut' = (n2w 3 : word2)) then (arm8_state_SCTLR_EL3 state) else (if bool_decide (scrut' = (n2w 0 : word2)) then (ARB : SCTLRType) else (let v := scrut' in (ARB : SCTLRType))))))).

