(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "BranchTo_def" *)
Definition BranchTo '((target0, branch_type) : (word64 * BranchType)) : (arm8_state -> arm8_state) :=
  (fun (state : arm8_state) => (let s1 := (Hint_Branch branch_type state) in
 (let s := (let scrut' := (ProcState_EL (arm8_state_PSTATE s1)) in (if bool_decide (scrut' = (n2w 0 : word2)) then (let s0 := (if ((word_bit 55 target0) && (TCR_EL1_TBI1 (arm8_state_TCR_EL1 s1))) then (bit_field_insert 63 56 (n2w 255 : word8) target0) else target0) in
