 ((if ((negb (word_bit 55 s0)) && (TCR_EL1_TBI0 (arm8_state_TCR_EL1 s1))) then (bit_field_insert 63 56 (n2w 0 : word8) s0) else s0), s1)) else (if bool_decide (scrut' = (n2w 2 : word2)) then ((if (TCR_EL2_EL3_TBI (arm8_state_TCR_EL2 s1)) then (bit_field_insert 63 56 (n2w 0 : word8) target0) else target0), s1) else (if bool_decide (scrut' = (n2w 3 : word2)) then ((if (TCR_EL2_EL3_TBI (arm8_state_TCR_EL3 s1)) then (bit_field_insert 63 56 (n2w 0 : word8) target0) else target0), s1) else (let v := scrut' in (ARB : (word64 * arm8_state)))))))) in
