(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "Align_def" *)
Definition Align {Nw : N} '((w, n) : ((word Nw) * N)) : (word Nw) :=
  ((n2w (n * ((w2n w) / n))) : (word Nw)).

(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "Aligned_def" *)
Definition Aligned {Nw : N} '((w, n) : ((word Nw) * N)) : bool :=
  (bool_decide (w = ((Align (Nw:=Nw)) (w, n)))).

(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "CheckSPAlignment_def" *)
Definition CheckSPAlignment (state : arm8_state) : arm8_state :=
  (if ((if (bool_decide ((ProcState_EL (arm8_state_PSTATE state)) = (n2w 0 : word2))) then (SCTLRType_SA0 (arm8_state_SCTLR_EL1 state)) else (SCTLRType_SA (SCTLR state))) && (negb ((Aligned (Nw:=64)) (((SP (Nw:=64)) state), 16)))) then (snd ((raise'exception (aT:=unit)) ALIGNMENT_FAULT state)) else state).

(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "CheckAlignment_def" *)
Definition CheckAlignment '((address, (size, (acctype, _iswrite))) : (word64 * (N * (AccType * bool)))) : (arm8_state -> arm8_state) :=
  (fun (state : arm8_state) => (if ((negb ((Aligned (Nw:=64)) (address, size))) && ((bool_decide (acctype = AccType_ATOMIC)) || ((bool_decide (acctype = AccType_ORDERED)) || (SCTLRType_A (SCTLR state))))) then (snd ((raise'exception (aT:=unit)) ALIGNMENT_FAULT state)) else state)).

(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "BigEndian_def" *)
Definition BigEndian (state : arm8_state) : bool :=
  (if (bool_decide ((ProcState_EL (arm8_state_PSTATE state)) = (n2w 0 : word2))) then (SCTLRType_E0E (arm8_state_SCTLR_EL1 state)) else (SCTLRType_EE (SCTLR state))).

(*! HOL "HOL/examples/l3-machine-code/arm8/model/arm8Script.sml" "ByteList_def" *)
Fixpoint ByteList (l : (list bool)) : (list (list bool)) :=
  (match l with
 | [] => []
 | (b0 :: []) => [[b0]]
 | (b0 :: (b1 :: [])) => [[b0; b1]]
 | (b0 :: (b1 :: (b2 :: []))) => [[b0; b1; b2]]
 | (b0 :: (b1 :: (b2 :: (b3 :: [])))) => [[b0; b1; b2; b3]]
 | (b0 :: (b1 :: (b2 :: (b3 :: (b4 :: []))))) => [[b0; b1; b2; b3; b4]]
 | (b0 :: (b1 :: (b2 :: (b3 :: (b4 :: (b5 :: [])))))) => [[b0; b1; b2; b3; b4; b5]]
 | (b0 :: (b1 :: (b2 :: (b3 :: (b4 :: (b5 :: (b6 :: []))))))) => [[b0; b1; b2; b3; b4; b5; b6]]
 | (b0 :: (b1 :: (b2 :: (b3 :: (b4 :: (b5 :: (b6 :: (v7 :: rest)))))))) => ([b0; b1; b2; b3; b4; b5; b6; v7] :: (ByteList rest))
 end).

